// Process data and prepare results
function buildFeatureRow(date) {
  const hour = date.getUTCHours() + date.getUTCMinutes() / 60;
  const yearStart = Date.UTC(date.getUTCFullYear(), 0, 0);
  const doy = (date.getTime() - yearStart) / 86400000;
  const dow = ((date.getUTCDay() + 6) % 7) + hour / 24;
  const f = [];
  for (const k of [1, 2, 3]) {
    f.push(Math.sin(2 * Math.PI * k * hour / 24));
    f.push(Math.cos(2 * Math.PI * k * hour / 24));
  }
  for (const k of [1, 2, 3]) {
    f.push(Math.sin(2 * Math.PI * k * doy / 365.25));
    f.push(Math.cos(2 * Math.PI * k * doy / 365.25));
  }
  for (const k of [1, 2]) {
    f.push(Math.sin(2 * Math.PI * k * dow / 7));
    f.push(Math.cos(2 * Math.PI * k * dow / 7));
  }
  return f;
}

const FEATURE_NAMES = [
  "hour_sin_1","hour_cos_1","hour_sin_2","hour_cos_2","hour_sin_3","hour_cos_3",
  "doy_sin_1","doy_cos_1","doy_sin_2","doy_cos_2","doy_sin_3","doy_cos_3",
  "dow_sin_1","dow_cos_1","dow_sin_2","dow_cos_2",
];

// Solve (XᵀX + αI) β = Xᵀy. Intercept column prepended, not regularized.
function solveRidge(X, y, alpha) {
  const n = X.length, p = X[0].length, P = p + 1;
  const XtX = Array.from({ length: P }, () => new Array(P).fill(0));
  const Xty = new Array(P).fill(0);
  for (let i = 0; i < n; i++) {
    const row = [1, ...X[i]];
    const yi = y[i];
    for (let a = 0; a < P; a++) {
      Xty[a] += row[a] * yi;
      for (let b = 0; b < P; b++) XtX[a][b] += row[a] * row[b];
    }
  }
  for (let k = 1; k < P; k++) XtX[k][k] += alpha;
  const A = XtX.map((r, i) => [...r, Xty[i]]);
  for (let col = 0; col < P; col++) {
    let pivot = col;
    for (let r = col + 1; r < P; r++) {
      if (Math.abs(A[r][col]) > Math.abs(A[pivot][col])) pivot = r;
    }
    if (Math.abs(A[pivot][col]) < 1e-12) {
      throw new Error(`Singular matrix at column ${col}.`);
    }
    if (pivot !== col) [A[col], A[pivot]] = [A[pivot], A[col]];
    for (let r = col + 1; r < P; r++) {
      const factor = A[r][col] / A[col][col];
      for (let c = col; c <= P; c++) A[r][c] -= factor * A[col][c];
    }
  }
  const beta = new Array(P).fill(0);
  for (let r = P - 1; r >= 0; r--) {
    let s = A[r][P];
    for (let c = r + 1; c < P; c++) s -= A[r][c] * beta[c];
    beta[r] = s / A[r][r];
  }
  return { intercept: beta[0], coefficients: beta.slice(1) };
}

// Mean absolute error helper
function mae(X, y, intercept, coef) {
  let sum = 0;
  for (let i = 0; i < X.length; i++) {
    let p = intercept;
    for (let j = 0; j < coef.length; j++) p += coef[j] * X[i][j];
    sum += Math.abs(p - y[i]);
  }
  return sum / X.length;
}

// ---------- Main ----------
const items = $input.all();
if (items.length < 20) {
  throw new Error(`Only ${items.length} rows — need ~20+ for a meaningful fit.`);
}

// Bucket by room, dedupe timestamps.
const perRoom = new Map();
const allTimestamps = [];

for (const { json: row } of items) {
  const ts = new Date(row.timestamp);
  if (isNaN(ts.getTime())) continue;
  const t = +row.temperature, h = +row.humidity;
  if (!Number.isFinite(t) || !Number.isFinite(h)) continue;
  const room = +row.room_id;
  if (!perRoom.has(room)) perRoom.set(room, new Map());
  const bucket = perRoom.get(room);
  const key = ts.toISOString();
  if (bucket.has(key)) {
    const prev = bucket.get(key);
    bucket.set(key, {
      ts,
      temperature: (prev.temperature + t) / 2,
      humidity:    (prev.humidity    + h) / 2,
    });
  } else {
    bucket.set(key, { ts, temperature: t, humidity: h });
  }
  allTimestamps.push(ts);
}

if (perRoom.size === 0) {
  throw new Error("No valid rows. Check the upstream items have timestamp / room_id / temperature / humidity.");
}

const ALPHA = 1.0;
const coefficients = { temperature: {}, humidity: {} };
const intercepts   = { temperature: {}, humidity: {} };
const stats        = { temperature: {}, humidity: {} };

// Also emit the in-sample fitted series so the web page can plot the Ridge
// curve overlaid on the actual data without re-fitting client-side.
const series = {};

for (const [room, bucket] of perRoom.entries()) {
  const rows = Array.from(bucket.values()).sort((a, b) => a.ts - b.ts);
  const X = rows.map(r => buildFeatureRow(r.ts));
  const yT = rows.map(r => r.temperature);
  const yH = rows.map(r => r.humidity);

  const rT = solveRidge(X, yT, ALPHA);
  const rH = solveRidge(X, yH, ALPHA);

  coefficients.temperature[String(room)] = rT.coefficients;
  coefficients.humidity   [String(room)] = rH.coefficients;
  intercepts  .temperature[String(room)] = rT.intercept;
  intercepts  .humidity   [String(room)] = rH.intercept;

  stats.temperature[String(room)] = {
    n_samples: rows.length,
    mae_train: Number(mae(X, yT, rT.intercept, rT.coefficients).toFixed(3)),
  };
  stats.humidity[String(room)] = {
    n_samples: rows.length,
    mae_train: Number(mae(X, yH, rH.intercept, rH.coefficients).toFixed(3)),
  };

  // Fitted values for plotting
  const fitT = X.map(x => {
    let s = rT.intercept;
    for (let j = 0; j < x.length; j++) s += rT.coefficients[j] * x[j];
    return Number(s.toFixed(3));
  });
  const fitH = X.map(x => {
    let s = rH.intercept;
    for (let j = 0; j < x.length; j++) s += rH.coefficients[j] * x[j];
    return Number(s.toFixed(3));
  });

  series[String(room)] = {
    timestamps:  rows.map(r => r.ts.toISOString()),
    actual: {
      temperature: yT.map(v => Number(v.toFixed(3))),
      humidity:    yH.map(v => Number(v.toFixed(3))),
    },
    ridge: {
      temperature: fitT,
      humidity:    fitH,
    },
  };
}

allTimestamps.sort((a, b) => a - b);

const model = {
  schema: "ridge-fourier-v2",
  targets: ["temperature", "humidity"],
  trained_at: new Date().toISOString(),
  alpha: ALPHA,
  feature_names: FEATURE_NAMES,
  rooms: Array.from(perRoom.keys()).sort((a, b) => a - b),
  coefficients,
  intercepts,
  data_range: {
    start: allTimestamps[0].toISOString(),
    end:   allTimestamps[allTimestamps.length - 1].toISOString(),
  },
  stats,
  series,
};

// Persist to workflow static data so the webhook prediction path can find it.
const staticData = $getWorkflowStaticData("global");
staticData.temperatureModel = model;

return [{ json: { model } }];

// Process data and prepare results
function buildFeatureRow(date) {
  const hour = date.getUTCHours() + date.getUTCMinutes() / 60;
  const yearStart = Date.UTC(date.getUTCFullYear(), 0, 0);
  const doy = (date.getTime() - yearStart) / 86400000;
  const dow = ((date.getUTCDay() + 6) % 7) + hour / 24;
  const f = [];
  for (const k of [1, 2, 3]) {
    f.push(Math.sin(2 * Math.PI * k * hour / 24));
    f.push(Math.cos(2 * Math.PI * k * hour / 24));
  }
  for (const k of [1, 2, 3]) {
    f.push(Math.sin(2 * Math.PI * k * doy / 365.25));
    f.push(Math.cos(2 * Math.PI * k * doy / 365.25));
  }
  for (const k of [1, 2]) {
    f.push(Math.sin(2 * Math.PI * k * dow / 7));
    f.push(Math.cos(2 * Math.PI * k * dow / 7));
  }
  return f;
}

function resolveModel() {
  const item = $input.item.json;
  if (item && item.model &&
      (item.model.schema === "ridge-fourier-v2" || item.model.schema === "ridge-fourier-v1")) {
    return item.model;
  }
  try {
    const staticData = $getWorkflowStaticData("global");
    if (staticData && staticData.temperatureModel) return staticData.temperatureModel;
  } catch (_) {}
  throw new Error(
    "No trained model available. Run the training workflow once first " +
    "(it writes the model to workflow static data)."
  );
}

function predictOne(model, target, roomKey, features) {
  // Handle both schema versions. v2 has coefficients.{target}.{room};
  // v1 has coefficients.{room} (temperature only).
  let coef, intercept;
  if (model.schema === "ridge-fourier-v2") {
    coef      = model.coefficients[target][roomKey];
    intercept = model.intercepts  [target][roomKey];
  } else {
    if (target !== "temperature") return null;
    coef      = model.coefficients[roomKey];
    intercept = model.intercepts  [roomKey];
  }
  if (!coef) return null;
  let p = intercept;
  for (let i = 0; i < coef.length; i++) p += coef[i] * features[i];
  return Number(p.toFixed(3));
}

// ---------- Main ----------
const item = $input.item.json;
const model = resolveModel();

if (!item.date) throw new Error("Missing `date` field on input item.");
const target = new Date(item.date);
if (isNaN(target.getTime())) throw new Error(`Invalid date: ${item.date}`);

const room = item.room_id != null ? +item.room_id : model.rooms[0];
const roomKey = String(room);
if (!model.rooms.includes(room)) {
  throw new Error(`Unknown room_id ${room}. Trained on: ${model.rooms.join(", ")}`);
}

const features = buildFeatureRow(target);
const temperature = predictOne(model, "temperature", roomKey, features);
const humidity    = predictOne(model, "humidity",    roomKey, features);

const dataEnd = new Date(model.data_range.end);
const daysPast = Math.max(0, (target.getTime() - dataEnd.getTime()) / 86400000);

return {
  json: {
    prediction: {
      temperature,
      humidity,
      room_id: room,
      date: target.toISOString(),
      model_trained_at: model.trained_at,
      model_data_range: model.data_range,
      extrapolation_days: Math.round(daysPast),
    },
  },
};

// Process data and prepare results
const predictionObj = $json.prediction || $json;

const predictedTemp = Number(predictionObj.temperature);
const predictedHum = Number(predictionObj.humidity);

const historicalRows = $("Load Historical Dataset").all();

const roomId = String(predictionObj.room_id);
const targetDate = new Date(predictionObj.date);
const targetMonth = targetDate.getMonth() + 1;

let filteredRows = historicalRows.filter(r => {
  const rowRoom = String(r.json.room_id) === roomId;
  const rowDate = new Date(r.json.timestamp);
  const rowMonth = rowDate.getMonth() + 1;
  return rowRoom && rowMonth === targetMonth;
});

if (filteredRows.length < 20) {
  filteredRows = historicalRows.filter(r => String(r.json.room_id) === roomId);
}

const temps = filteredRows.map(r => Number(r.json.temperature)).filter(Number.isFinite);
const hums = filteredRows.map(r => Number(r.json.humidity)).filter(Number.isFinite);

function mean(arr) {
  return arr.reduce((sum, v) => sum + v, 0) / arr.length;
}

const tempMean = temps.length ? mean(temps) : 22;
const humMean = hums.length ? mean(hums) : 55;

// Realistic UAE indoor monthly thresholds
const comfortMap = {
  1:  { tLow: 21, tHigh: 24, hLow: 40, hHigh: 65 },
  2:  { tLow: 21, tHigh: 24, hLow: 40, hHigh: 65 },
  3:  { tLow: 22, tHigh: 24, hLow: 40, hHigh: 65 },
  4:  { tLow: 22, tHigh: 25, hLow: 40, hHigh: 68 },
  5:  { tLow: 20, tHigh: 23, hLow: 45, hHigh: 70 },
  6:  { tLow: 19, tHigh: 22, hLow: 45, hHigh: 72 },
  7:  { tLow: 19, tHigh: 22, hLow: 45, hHigh: 75 },
  8:  { tLow: 19, tHigh: 22, hLow: 45, hHigh: 75 },
  9:  { tLow: 20, tHigh: 23, hLow: 45, hHigh: 72 },
  10: { tLow: 21, tHigh: 24, hLow: 40, hHigh: 68 },
  11: { tLow: 21, tHigh: 24, hLow: 40, hHigh: 65 },
  12: { tLow: 21, tHigh: 24, hLow: 40, hHigh: 65 }
};

const c = comfortMap[targetMonth];

// Small dataset adjustment only
const tempAdj = Math.max(-0.5, Math.min(0.5, tempMean - ((c.tLow + c.tHigh) / 2)));
const humAdj = Math.max(-3, Math.min(3, humMean - ((c.hLow + c.hHigh) / 2)));

const tempLower = Number((c.tLow + tempAdj).toFixed(1));
const tempUpper = Number((c.tHigh + tempAdj).toFixed(1));
const humLower = Number((c.hLow + humAdj).toFixed(1));
const humUpper = Number((c.hHigh + humAdj).toFixed(1));

function classify(value, lower, upper) {
  if (value > upper) return "High Anomaly";
  if (value < lower) return "Low Anomaly";
  return "Normal";
}

return {
  json: {
    prediction: {
      ...predictionObj,

      temperature_status: classify(predictedTemp, tempLower, tempUpper),
      humidity_status: classify(predictedHum, humLower, humUpper),

      temp_lower: tempLower,
      temp_upper: tempUpper,
      hum_lower: humLower,
      hum_upper: humUpper,

      temp_mean: Number(tempMean.toFixed(1)),
      hum_mean: Number(humMean.toFixed(1)),

      threshold_month: targetMonth,
      threshold_samples: filteredRows.length,

      _backendBadge: "regression"
    }
  }
};

// Process data and prepare results
const p = $json.prediction || $json;

const tempStatus = p.temperature_status;
const humStatus = p.humidity_status;

const idealTemp = Number(p.temp_mean || 22).toFixed(1);
const idealHum = Number(p.hum_mean || 55).toFixed(1);

const tips = [];

if (tempStatus === "High Anomaly") {
  tips.push(`Decrease temperature toward ${idealTemp}°C to maintain a comfortable environment.`);
} else if (tempStatus === "Low Anomaly") {
  tips.push(`Increase temperature toward ${idealTemp}°C to maintain a comfortable environment.`);
}

if (humStatus === "High Anomaly") {
  tips.push(`Decrease humidity toward ${idealHum}% using ventilation or dehumidification.`);
} else if (humStatus === "Low Anomaly") {
  tips.push(`Increase humidity toward ${idealHum}% to maintain indoor comfort.`);
}

if (tips.length === 0) {
  tips.push(`Conditions are normal. Maintain temperature near ${idealTemp}°C and humidity near ${idealHum}%.`);
}

return {
  json: {
    prediction: {
      ...p,
      recommended_temperature: Number(idealTemp),
      recommended_humidity: Number(idealHum),
      recommendation: tips.join(" ")
    }
  }
};

parameters.responseBody:
={{ (() => {
  const p = $("Anomaly Detection Engine").item.json.prediction;

  let rec = "Conditions are normal. Maintain current settings.";

  if (p.temperature_status === "High Anomaly") {
    rec = `Temperature is above the normal threshold. Decrease temperature toward ${((p.temp_lower + p.temp_upper) / 2).toFixed(1)}°C.`;
  } else if (p.temperature_status === "Low Anomaly") {
    rec = `Temperature is below the normal threshold. Increase temperature toward ${((p.temp_lower + p.temp_upper) / 2).toFixed(1)}°C.`;
  }

  if (p.humidity_status === "High Anomaly") {
    rec += ` Humidity is high. Use ventilation or dehumidification toward ${((p.hum_lower + p.hum_upper) / 2).toFixed(1)}%.`;
  } else if (p.humidity_status === "Low Anomaly") {
    rec += ` Humidity is low. Increase humidity toward ${((p.hum_lower + p.hum_upper) / 2).toFixed(1)}%.`;
  }

  return {
    ...p,
    recommendation: rec
  };
})() }}
